"""Render only completed independent revision review; missing runs remain visible."""
from pathlib import Path
import json
from html import escape
def render(out,link,image):
 r=out/'reports';p=r/'review_v2_qualification.json'
 if not p.exists():return ''
 q=json.loads(p.read_text(encoding='utf-8'));rows=[]
 for c in q['case_results']:
  label=c['label'];n=q['numerical_results'].get(label)
  if n is None:
   rows.append(f'<tr><td>{escape(label)}</td><td colspan="8">Çalışılmadı / alan yok: {escape(c.get("reason") or c.get("status","eksik"))}</td></tr>');continue
  v=n['values'];e=c['original_table_corrected_reference'];rows.append(f'<tr><td>{escape(label)}</td><td>{n["mesh"]["cells"]:,}</td><td>{v["field_iteration"]} / {v["terminal_iteration"]}</td><td>{v["CL"]:.7f}</td><td>{v["CD"]:.8f}</td><td>{v["density_log10"]:.4f}</td><td>{v["max_yplus"]:.4f}</td><td>{v["CL_tail200_range"]:.3g} / {v["CD_tail200_range"]:.3g}</td><td>{e["all"]["RMSE"]:.5f} / {e["all"]["max_abs_error"]:.5f}</td></tr>')
 passed=q['minimum_qualification_passed'];num=q['all_required_numerical_gates_passed'];gate=[]
 for name,title in [('grid_sensitivity','Orta→ince ağ'),('farfield_sensitivity','Uzak alan')]:
  d=q[name]
  if not d['evaluated']:gate.append(f'<li>{title}: henüz değerlendirilemedi; gerekli alan eksik.</li>')
  else:gate.append(f'<li>{title}: CL %{100*d["CL_relative_change"]:.4f}; CD %{100*d["CD_relative_change"]:.4f}; bütün alt kapılar {"geçti" if all(d["checks"].values()) else "geçmedi"}. Yakınsamış girişler: {"evet" if d["converged_inputs"] else "hayır; fark yalnız tanıdır"}.</li>')
 profile_rows=[];figures=[]
 for label,n in q['numerical_results'].items():
  # n.folder is project-root relative; derive root from the known output nesting.
  root=out.parents[2];folder=root/n['folder'];pp=folder/'boundary_layer_profile_audit.json'
  if not pp.exists():continue
  d=json.loads(pp.read_text(encoding='utf-8'));it=d['field_checkpoint']['iteration'];current=it==n['values']['field_iteration']
  for row in d['profiles']:
   delta=row['edge_definitions']['far_outer']['operational_delta99_c'];nr=row['normal_resolution'];step=nr['max_normal_interval_below_operational_delta99_m'];ratio=step/delta if delta and step else None
   profile_rows.append(f'<tr><td>{escape(label)} / {it}{"" if current else " (ayrı ara alan)"}</td><td>{row["side"]} / {row["station_x_over_c"]}</td><td>{delta:.5f}c</td><td>{nr["normal_cells_below_operational_delta99"]}</td><td>{100*ratio:.2f}%</td><td>{row["prescribed_quad_layer_thickness_c"]:.3f}c</td></tr>' if delta and ratio else f'<tr><td>{escape(label)} / {it}</td><td>{row["side"]} / {row["station_x_over_c"]}</td><td colspan="4">Operasyonel dış kenar belirsiz</td></tr>')
  if current:
   fig=out/'plots'/f'prediction_v2_BL_velocity_{folder.name}_iter{it:06d}.png'
   if fig.exists():figures.append(image(fig,f'{label}: gerçek normal hız profilleri, tam alan adımı{it}; kırmızı çizgi dörtgen katman sonu.'))
 profile_section=''
 if profile_rows:profile_section=f'<h3>Sınır tabakasının tamamı ayrıca incelendi</h3><p>Ue, her çözümün kendi0,05–0,08c dış penceresindeki teğetsel hız medyanıdır;0,025–0,045c ikinci tanımın duyarlılığı da ham kayıtta korunur. δ99 bu operasyonel tanıma aittir; basınç gradyanı nedeniyle kesin bir deneysel kenar değildir. Dörtgen blok dışındaki üçgenler akışı çözebilir; gerçek normal hücre aralıkları ve çözüm duyarlılığı değerlendirilmeden kapsama uyarısı tek başına hata sayılmaz.</p><div class="scroll"><table><tr><th>Koşu/alan adımı</th><th>Yüzey/x/c</th><th>Operasyonel δ99</th><th>δ99 içindeki normal kesit hücresi</th><th>Max normal adım/δ99</th><th>Dörtgen blok</th></tr>{"".join(profile_rows)}</table></div>{"".join(figures)}'
 missing=q['critical_regional_mesh_issue_open'];why='Aynı fiziksel koşullarda yakınsamış iki orta çözüm arasında, dörtgen normal katmanı0,01c’den0,02c’ye çıkarmak CL’yi%3,9766 ve CD’yi%4,6762 değiştirdi; yüzey Cp farkı RMSE0,034097. Üç ana seviyenin küçük farkı bu bölgesel duyarlılığı kapatmıyor.0,03c/0,04c katmanlar kesişme nedeniyle reddedildi.400c alanı hazırlanmış olsa da çözüm çalıştırılmadı.'
 diagnostic_section=f'''<h3>Tek değişkenli tanılar ve kalan sorun</h3><p>Normal katman değişikliğinde iki çözüm de iteratif ve y+ kabulünü sağlıyor. Bu yüzden fark yalnız yakınsamamış bir çözümle açıklanamaz. Değişen kalınlık ağın bağlantısını da etkileyebilir; sonuç bu katman üretim düzenine duyarlılığı gösterir, tek başına bir hücrenin hatasını kanıtlamaz.</p><p>Sonradan dondurulmuş tanılar da özgün tabloyla kıyaslandı: eski eğri/40c üzerinde JST Cp RMSE0,05814, JST_MAT0,07088; yeni r2 eğri/200c üzerinde0,02c orta prototip0,05004. Hiçbiri0,03 sınırını geçmedi. Bunlar seçilmiş ana aileye sonradan yerleştirilmedi; tek bir daha iyi prototip üç ağ ve uzak alan kabulünün yerine geçmez.</p><p>İnce çözümün ilk denemesinde yoğunluk kalıntısı alt yüzey x/c≈0,745–0,75 mikrokatmanlarında yoğunlaştı. Aynı ağ/restart/akı altında sabit CFL1 devamıyla kayıtlı son3400 alanında sayısal kapılar geçti; terminal3468 satırı bu alanla karıştırılmadı.1300s süre sınırındaki son tam ara alan korunuyor.</p><p>Profil algoritması2, dış hız ve kenar aramasında yalnız geçerli VTK örneklerini kullanır. Eski algoritma ve geçersiz örnek konumları saklandı. Yeniden kontrol edilen profillerin sonucu değişmedi; ham CFD alanı ve kuvvetler değişmedi. Operasyonel δ99, özellikle alt arka bölümde Ue penceresine duyarlı olduğu için kesin fiziksel sınır tabakası kalınlığı diye sunulmaz.</p><p>{link(r/'prediction_v2_numerical_summary.json','Analizcinin dondurulmuş sayısal özeti')} · {link(r/'prediction_v2_normal_resolution_comparison.json','Aynı istasyonlarda normal profil farkları')} · {link(r/'prediction_v2_mesh_prototype_failures.json','Reddedilen ağlar ve nedenleri')} · {link(r/'review_frozen_diagnostics.json','Tüm tamamlanan tanıların ayrı deney kıyası')} · {link(r/'review_v2_integrity.json','649 dosyanın bağımsız SHA doğrulaması')}</p>'''
 return f'''<section><h2>İkinci seri: dondurulmuş tahminin bağımsız sonucu</h2><p class="warn">Asgari yeterlilik: {"bu tek vaka kapsamında geçti" if passed else "geçmedi"}. Gerekli sayısal kapılar: {"geçti" if num else "tamamı geçmedi"}. Kritik bölgesel ağ açığı: {"var" if missing else "kayıtlı değerlendirmede kapatıldı"}.</p><p>{escape(why)}</p><p>Doğrulama tahmini olarak önceden tanımlı en ince ağ seçildi; en iyi deney uyumunu veren koşu seçilmedi. Kaba/orta/uzak alan ve başarısız tanıların bütün farkları saklanır. Aynı eşikler ve kaynak tabloyla belgeli tek işaret düzeltmesi kullanıldı.</p><div class="scroll"><table><tr><th>Koşu</th><th>Hücre</th><th>Alan / terminal adımı</th><th>CL</th><th>CD</th><th>Yoğunluklog10</th><th>maxy+</th><th>Son200 CL / CD aralığı</th><th>Özgün tablo Cp RMSE / max fark</th></tr>{''.join(rows)}</table></div><ul>{''.join(gate)}</ul><p>Alanı olmayan koşuya Cp/y+ atanmadı. Yakınsamamış ama kayıtlı bir alanın deney kıyası yalnız tanıdır; ağdan bağımsız sonuç sayılmaz. GCI/Richardson bandı raporlanmadı. V1–v2 toplam farkından eğri, dış alan ve akı yönteminin tek tek nedensel payı çıkarılamaz; tek değişkenli tanılar ayrı tutuldu.</p>{image(out/'plots/review_v2_Cp_comparison.png','Dondurulmuş v2 alanları, özgün deney tablosu ve tüm103 noktada hata.')}<p>{link(r/'prediction_v2_frozen.json','V2 ham çıktı mühürü')} · {link(p,'Bağımsız v2 sayısal/deney kalite kaydı')} · {link(r/'review_physical_config_audit.json','Gerçek fiziksel koşul denetimi')} · {link(r/'review_v2_topology.json','Bağımsız dışa aktarılmış ağ topolojisi')}</p>{profile_section}{diagnostic_section}</section>'''
